import { format, parseISO } from "date-fns";
import { ChevronDown, Plus } from "lucide-react";
import { useMemo, useState } from "react";
import { UseFormReturn } from "react-hook-form";
import { useTranslation } from "react-i18next";

import CareIcon from "@/CAREUI/icons/CareIcon";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import {
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import {
  Popover,
  PopoverAnchor,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";

import { cn } from "@/lib/utils";

import { add, isPositive, round } from "@/Utils/decimal";
import { dateQueryString } from "@/Utils/utils";
import { MonetaryComponentSelector } from "@/components/Billing/MonetaryComponentSelector";
import { ResourceCategoryPicker } from "@/components/Common/ResourceCategoryPicker";
import { SchemaField } from "@/components/Extensions/SchemaField";
import { CURRENCY_SYMBOL } from "@/components/ui/monetary-display";
import { ProcessedExtension } from "@/hooks/useExtensions";
import { ProductKnowledgeSelect } from "@/pages/Facility/services/inventory/ProductKnowledgeSelect";
import useCurrentFacility from "@/pages/Facility/utils/useCurrentFacility";
import { Code } from "@/types/base/code/code";
import {
  MonetaryComponent,
  MonetaryComponentType,
} from "@/types/base/monetaryComponent/monetaryComponent";
import { ResourceCategoryResourceType } from "@/types/base/resourceCategory/resourceCategory";
import { ProductRead } from "@/types/inventory/product/product";

import { SupplyDeliveryFormValues } from "./AddSupplyDeliveryForm";
import { DeliveryMonetaryInput } from "./DeliveryMonetaryInput";
import { useDeliveryItem } from "./useDeliveryItem";

interface Props {
  form: UseFormReturn<SupplyDeliveryFormValues>;
  informationalCodes: Code[];
  autoOpenProductSelect?: boolean;
  onProductSelectOpened?: () => void;
  processedExtensions: ProcessedExtension[];
  locationId?: string;
}

export function ExternalDeliveryItemFields({
  form,
  informationalCodes,
  autoOpenProductSelect = false,
  onProductSelectOpened,
  processedExtensions,
  locationId,
}: Props) {
  const { facilityId } = useCurrentFacility();
  const { t } = useTranslation();
  const [batchSelectorOpen, setBatchSelectorOpen] = useState(false);

  const extensionsWithFields = useMemo(
    () =>
      processedExtensions.filter(
        ({ fieldMetadata }) => fieldMetadata.length > 0,
      ),
    [processedExtensions],
  );

  const {
    productKnowledge,
    suppliedItem,
    batchNumber,
    unitPrice,
    purchasePrice,
    totalPurchasePrice,
    packSize,
    taxComponents,
    discountComponents,
    informationalComponents,
    chargeItemCategory,
    isTaxInclusive,
    isReplacement,
    replacesDelivery,
    needsCategorySelection,
    isCreatingNew,
    isLoadingProducts,
    products,
    inventoryByProductId,
    availableTaxes,
    availableDiscounts,
    setField,
    resetFields,
    markAsEdited,
    fillFromProduct,
    updateInformationalComponent,
  } = useDeliveryItem({ form, locationId });

  const filteredProducts = products.filter(
    (product) =>
      !batchNumber ||
      product.batch?.lot_number
        ?.toLowerCase()
        .includes(batchNumber.toLowerCase()),
  );
  const totalNetContent =
    locationId && filteredProducts.length > 0
      ? add(
          ...filteredProducts.map(
            (product) =>
              inventoryByProductId.get(product.id)?.net_content || "0",
          ),
        )
      : null;
  const unit = productKnowledge?.base_unit?.display || t("units");

  const handleProductSelect = (product: ProductRead) => {
    fillFromProduct(product);
    setBatchSelectorOpen(false);
  };

  const getExpirationDisplay = (product: ProductRead) => {
    const expiry = dateQueryString(product.expiration_date);
    return expiry ? format(parseISO(expiry), "MMM yyyy") : "-";
  };

  return (
    <div className="space-y-6" data-pending-delivery-id={replacesDelivery?.id}>
      <section className="space-y-4">
        <h3 className="text-sm font-semibold text-gray-950">
          {t("product_details")}
        </h3>
        <FormField
          control={form.control}
          name="item.product_knowledge"
          render={({ field }) => (
            <FormItem>
              <FormLabel>{t("product")}</FormLabel>
              <FormControl>
                <ProductKnowledgeSelect
                  value={field.value}
                  onChange={(value) => {
                    field.onChange(value);
                    onProductSelectOpened?.();
                    resetFields();
                  }}
                  placeholder={t("select_product")}
                  className="w-full"
                  disabled={isReplacement}
                  disableFavorites
                  hideClearButton
                  defaultOpen={autoOpenProductSelect && !isReplacement}
                />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          <FormField
            control={form.control}
            name="item.batch_number"
            render={({ field }) => (
              <FormItem>
                <FormLabel>{t("batch_no")}</FormLabel>
                <Popover
                  open={batchSelectorOpen}
                  onOpenChange={setBatchSelectorOpen}
                >
                  <PopoverAnchor asChild>
                    <div className="flex gap-1">
                      <FormControl>
                        <Input
                          {...field}
                          value={batchNumber || ""}
                          onChange={(event) => {
                            field.onChange(event);
                            markAsEdited();
                            if (event.target.value) setBatchSelectorOpen(true);
                          }}
                          onClick={() => setBatchSelectorOpen(true)}
                          placeholder={t("batch_no")}
                          disabled={!productKnowledge}
                          className={cn(
                            "min-w-0",
                            isCreatingNew && "border-primary-300 bg-primary-50",
                          )}
                        />
                      </FormControl>
                      <PopoverTrigger asChild>
                        <Button
                          type="button"
                          variant="outline"
                          size="icon"
                          disabled={!productKnowledge}
                          aria-label={t("select_batch")}
                          className="shrink-0"
                        >
                          <ChevronDown className="size-4" />
                        </Button>
                      </PopoverTrigger>
                    </div>
                  </PopoverAnchor>
                  <PopoverContent
                    className="w-80 max-w-[calc(100vw-2rem)] p-0"
                    align="start"
                    onOpenAutoFocus={(event) => event.preventDefault()}
                  >
                    <Command>
                      <CommandList className="max-h-64">
                        {batchNumber && (
                          <CommandGroup>
                            <CommandItem
                              onSelect={() => {
                                markAsEdited();
                                setBatchSelectorOpen(false);
                              }}
                            >
                              <Plus className="size-4 text-primary-700" />
                              <span>
                                {t("create_batch")}:{" "}
                                <strong>{batchNumber}</strong>
                              </span>
                            </CommandItem>
                          </CommandGroup>
                        )}
                        {isLoadingProducts ? (
                          <div className="py-6 text-center text-sm">
                            <CareIcon
                              icon="l-spinner"
                              className="mx-auto mb-2 size-4 animate-spin"
                            />
                            {t("loading")}
                          </div>
                        ) : products.length === 0 ? (
                          !batchNumber && (
                            <CommandEmpty>
                              {t("type_batch_number")}
                            </CommandEmpty>
                          )
                        ) : (
                          <CommandGroup
                            heading={
                              <span className="flex w-full items-center justify-between gap-2">
                                <span>{t("existing_batches")}</span>
                                {totalNetContent !== null && (
                                  <Badge
                                    variant={
                                      isPositive(totalNetContent)
                                        ? "primary"
                                        : "secondary"
                                    }
                                    className="text-xs"
                                  >
                                    {round(totalNetContent)} {unit}
                                  </Badge>
                                )}
                              </span>
                            }
                          >
                            {filteredProducts.map((product) => {
                              const netContent = inventoryByProductId.get(
                                product.id,
                              )?.net_content;
                              return (
                                <CommandItem
                                  key={product.id}
                                  value={product.id}
                                  onSelect={() => handleProductSelect(product)}
                                >
                                  <div className="flex w-full items-center justify-between gap-2">
                                    <div className="min-w-0">
                                      <p className="truncate font-medium">
                                        {product.batch?.lot_number || "-"}
                                      </p>
                                      <p className="text-xs text-muted-foreground">
                                        {t("expiry_short")}:{" "}
                                        {getExpirationDisplay(product)}
                                      </p>
                                    </div>
                                    <div className="flex shrink-0 items-center gap-2">
                                      {locationId &&
                                        netContent !== undefined && (
                                          <Badge
                                            variant={
                                              isPositive(netContent)
                                                ? "primary"
                                                : "destructive"
                                            }
                                            className="text-xs"
                                          >
                                            {round(netContent)} {unit}
                                          </Badge>
                                        )}
                                      {suppliedItem?.id === product.id && (
                                        <CareIcon
                                          icon="l-check"
                                          className="size-4 text-primary-600"
                                        />
                                      )}
                                    </div>
                                  </div>
                                </CommandItem>
                              );
                            })}
                          </CommandGroup>
                        )}
                      </CommandList>
                    </Command>
                  </PopoverContent>
                </Popover>
                {isCreatingNew && (
                  <Badge variant="outline" className="w-fit text-primary-700">
                    {t("new")}
                  </Badge>
                )}
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="item.expiry_date"
            render={({ field }) => (
              <FormItem>
                <FormLabel>{t("expiry_date")}</FormLabel>
                <FormControl>
                  <Input
                    {...field}
                    type="date"
                    onChange={(event) => {
                      field.onChange(event);
                      markAsEdited();
                    }}
                    disabled={!productKnowledge}
                    className="min-w-0"
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />

          <FormField
            control={form.control}
            name="item.charge_item_category"
            render={() => (
              <FormItem>
                <FormLabel>{t("category")}</FormLabel>
                {needsCategorySelection ? (
                  <FormControl>
                    <ResourceCategoryPicker
                      facilityId={facilityId}
                      resourceType={
                        ResourceCategoryResourceType.charge_item_definition
                      }
                      value={chargeItemCategory}
                      onValueChange={(category) => {
                        setField("charge_item_category", category?.slug || "");
                        setField(
                          "tax_components",
                          category?.configured_monetary_components?.filter(
                            (component): component is MonetaryComponent =>
                              component.monetary_component_type ===
                              MonetaryComponentType.tax,
                          ) || [],
                        );
                        markAsEdited(true);
                      }}
                      placeholder={t("select_category")}
                      className="w-full min-w-0"
                    />
                  </FormControl>
                ) : (
                  <FormControl>
                    <Input
                      value={
                        suppliedItem?.charge_item_definition?.category?.title ||
                        "-"
                      }
                      disabled
                    />
                  </FormControl>
                )}
                <FormMessage />
              </FormItem>
            )}
          />
        </div>
      </section>

      <section className="space-y-4 border-t pt-5">
        <h3 className="text-sm font-semibold text-gray-950">{t("quantity")}</h3>
        <div className="grid gap-4 sm:grid-cols-3">
          <FormField
            control={form.control}
            name="item.supplied_item_pack_size"
            render={() => (
              <FormItem>
                <FormLabel>{t("pack_size")}</FormLabel>
                <FormControl>
                  <Input
                    type="number"
                    min={1}
                    step={1}
                    value={packSize || ""}
                    aria-label={t("pack_size")}
                    placeholder="0"
                    onChange={(event) => {
                      setField(
                        "supplied_item_pack_size",
                        parseInt(event.target.value) || undefined,
                      );
                      markAsEdited(Boolean(isTaxInclusive));
                    }}
                    disabled={!productKnowledge}
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="item.supplied_item_pack_quantity"
            render={({ field }) => (
              <FormItem>
                <FormLabel>{t("pack_qty")}</FormLabel>
                <FormControl>
                  <Input
                    {...field}
                    type="number"
                    min={1}
                    step={1}
                    required
                    value={field.value ?? ""}
                    aria-label={t("pack_qty")}
                    data-pending-item-quantity
                    placeholder={t("pack_qty")}
                    onChange={(event) =>
                      field.onChange(
                        event.target.value === ""
                          ? null
                          : Number(event.target.value),
                      )
                    }
                    disabled={!productKnowledge?.slug}
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="item.supplied_item_quantity"
            render={({ field }) => (
              <FormItem>
                <FormLabel>{t("qty")}</FormLabel>
                <FormControl>
                  <Input
                    {...field}
                    type="number"
                    min={1}
                    aria-label={t("qty")}
                    disabled
                  />
                </FormControl>
                <FormMessage />
              </FormItem>
            )}
          />
        </div>
      </section>

      <section className="space-y-4 border-t pt-5">
        <h3 className="text-sm font-semibold text-gray-950">{t("sale")}</h3>
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          <FormField
            control={form.control}
            name="item.unit_price"
            render={() => (
              <FormItem>
                <FormLabel>{t("item_price")}</FormLabel>
                <div className="flex items-center gap-2">
                  <span className="text-sm text-gray-500" aria-hidden>
                    {CURRENCY_SYMBOL}
                  </span>
                  <FormControl>
                    <DeliveryMonetaryInput
                      value={unitPrice}
                      aria-label={t("item_price")}
                      placeholder="0"
                      onValueChange={(value) => {
                        setField("unit_price", value);
                        markAsEdited(true);
                      }}
                      disabled={!productKnowledge || isTaxInclusive}
                      className="min-w-0"
                    />
                  </FormControl>
                </div>
                <FormMessage />
              </FormItem>
            )}
          />
          {informationalCodes.map((code) => {
            const currentValue = informationalComponents?.find(
