                <Checkbox
                  checked={isTaxInclusive || false}
                  onCheckedChange={(checked) => {
                    setField("is_tax_inclusive", !!checked);
                    markAsEdited(true);
                  }}
                  disabled={!productKnowledge}
                />
              </FormControl>
              <FormLabel className="font-normal">
