              selectedComponents={discountComponents || []}
              onSelectionChange={(components) => {
                setField("discount_components", components);
                markAsEdited(true);
              }}
              disabled={!productKnowledge}
              displayMode="full"
            />
          </div>
        </div>
      </section>

      <section className="space-y-4 border-t pt-5">
        <h3 className="text-sm font-semibold text-gray-950">{t("purchase")}</h3>
        <div className="grid gap-4 sm:grid-cols-2">
          <FormField
            control={form.control}
            name="item.total_purchase_price"
            render={() => (
              <FormItem>
                <FormLabel>{t("total_purchase_price")}</FormLabel>
                <div className="flex items-center gap-2">
                  <span className="text-sm text-gray-500" aria-hidden>
                    {CURRENCY_SYMBOL}
                  </span>
                  <FormControl>
                    <DeliveryMonetaryInput
                      value={totalPurchasePrice}
                      aria-label={t("tpr")}
                      placeholder="0"
                      onValueChange={(value) => {
                        setField("total_purchase_price", value || undefined);
                        setField("is_total_purchase_price_edited", true);
                        markAsEdited();
                      }}
                      disabled={!productKnowledge}
                      className="min-w-0"
                    />
                  </FormControl>
                </div>
                <FormMessage />
              </FormItem>
            )}
          />
          <FormField
            control={form.control}
            name="item.purchase_price"
            render={() => (
              <FormItem>
                <FormLabel>{t("purchase_price")}</FormLabel>
                <div className="flex items-center gap-2">
                  <span className="text-sm text-gray-500" aria-hidden>
                    {CURRENCY_SYMBOL}
                  </span>
                  <FormControl>
                    <DeliveryMonetaryInput
                      value={purchasePrice}
