}

interface AllSupplyDeliveriesProps {
  facilityId: string;
  deliveryOrder: DeliveryOrderRetrieve;
  locationId: string;
  internal: boolean;
  isRequester: boolean;
  selectedProductKnowledge?: ProductKnowledgeBase;
}

function AllSupplyDeliveriesComponent({
  facilityId,
  deliveryOrder,
  locationId,
  internal,
  isRequester,
  selectedProductKnowledge,
}: AllSupplyDeliveriesProps) {
  const { t } = useTranslation();

  const qParams = {
    ...(internal
      ? {
          supplied_inventory_item_product_knowledge:
            selectedProductKnowledge?.id,
        }
      : {
          supplied_item_product_knowledge: selectedProductKnowledge?.id,
        }),
    ...(internal
      ? {
          ...(isRequester
            ? {
                origin: deliveryOrder.origin?.id,
                destination: locationId,
              }
            : {
                origin: locationId,
                destination: deliveryOrder.destination?.id,
              }),
        }
      : {
          supplier: deliveryOrder?.supplier?.id,
          destination: isRequester ? locationId : deliveryOrder.destination?.id,
        }),
  };

  const { data: allSupplyDeliveries, isLoading: isLoadingAllSupplyDeliveries } =
    useQuery({
      queryKey: ["allSupplyDeliveries", qParams],
      queryFn: query.paginated(supplyDeliveryApi.listSupplyDelivery, {
        queryParams: {
          facility: facilityId,
          ...qParams,
        },
      }),
    });

  return (
    <div className="pt-2">
      <div className="space-y-4 max-h-[68vh] overflow-y-auto px-4 pt-4">
        {isLoadingAllSupplyDeliveries ? (
          <TableSkeleton count={3} />
        ) : allSupplyDeliveries?.results &&
          allSupplyDeliveries.results.length > 0 ? (
          <>
            <SupplyDeliveryTable
              deliveries={allSupplyDeliveries.results}
              internal={internal}
              facilityId={facilityId}
              linkToProduct
            />
          </>
        ) : (
          <EmptyState
            icon={<Truck className="size-5 text-primary-600" />}
            title={t("no_deliveries_found")}
            description={t("no_deliveries_found_description")}
          />
        )}
      </div>
    </div>
  );
}

function getDeliveryOrderStatusActions(
  status: DeliveryOrderStatus,
  internal: boolean,
  anyCompletedSupplyDeliveries: boolean,
) {
  const isPendingOrCompleted = [
    DeliveryOrderStatus.draft,
    DeliveryOrderStatus.pending,
    DeliveryOrderStatus.completed,
  ].includes(status);
  if (
    (internal && status !== DeliveryOrderStatus.draft) ||
    (!internal && !isPendingOrCompleted)
  ) {
    return [];
  }

  const actions = [
    {
      status: DeliveryOrderStatus.draft,
      icon: <Edit className="size-4" />,
      label: "mark_as_draft",
      visibility: true,
    },
    {
      status: DeliveryOrderStatus.entered_in_error,
      icon: <CareIcon icon="l-exclamation-circle" />,
      label: "mark_as_entered_in_error",
      visibility: internal ? true : !anyCompletedSupplyDeliveries,
    },
    {
      status: DeliveryOrderStatus.abandoned,
      icon: <CareIcon icon="l-ban" />,
      label: "mark_as_abandoned",
      visibility: internal ? true : !anyCompletedSupplyDeliveries,
    },
  ];
  return actions.filter(
    (action) => action.status !== status && action.visibility,
  );
}

export function DeliveryOrderShow({
  facilityId,
  deliveryOrderId,
  locationId,
  internal,
}: Props) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const { getExtensions } = useExtensionSchemas();

  const allExtensions = getExtensions(
    ExtensionEntityType.supply_delivery_order,
    "retrieve",
  );

  const extensionFields = useMemo(
    () =>
      getExtensionFieldsWithName(
        allExtensions,
        ExtensionContexts.supply_delivery_order_summary,
      ),
    [allExtensions],
  );

  const [selectedDeliveries, setSelectedDeliveries] = useState<string[]>([]);
  const [confirmDialog, setConfirmDialog] = useState({
    open: false,
    status: SupplyDeliveryStatus.completed,
    condition: SupplyDeliveryCondition.normal,
  });
  const [showAllDeliveries, setShowAllDeliveries] = useState(false);
  const [showCancelledDeliveries, setShowCancelledDeliveries] = useState(false);
  const deliveryFormRef = useRef<AddSupplyDeliveryFormHandle>(null);
  const [editingDeliveryIds, setEditingDeliveryIds] = useState<string[]>([]);
  const [hasPendingItemChanges, setHasPendingItemChanges] = useState(false);
  const [selectedProductKnowledgeDrawer, setSelectedProductKnowledgeDrawer] =
    useState<ProductKnowledgeBase>();
  const [deliveryOrderStatusDialog, setDeliveryOrderStatusDialog] = useState<{
    open: boolean;
    status: DeliveryOrderStatus | null;
  }>({
    open: false,
    status: null,
  });
  const { open: isSidebarOpen } = useSidebar();

  const { data: deliveryOrder, isLoading } = useQuery({
    queryKey: ["deliveryOrders", deliveryOrderId],
    queryFn: query(deliveryOrderApi.retrieveDeliveryOrder, {
      pathParams: {
        facilityId: facilityId,
        deliveryOrderId: deliveryOrderId,
      },
    }),
  });

  const isRequester = locationId === deliveryOrder?.destination.id;

  const {
    data: supplyDeliveries,
    isLoading: isLoadingSupplyDeliveries,
    isFetching: isFetchingSupplyDeliveries,
  } = useQuery({
    queryKey: ["supplyDeliveries", deliveryOrderId],
    queryFn: query.paginated(supplyDeliveryApi.listSupplyDelivery, {
      queryParams: {
        order: deliveryOrderId,
        facility: facilityId,
        ordering: "created_date",
      },
    }),
  });

  const supplyOrderId = supplyDeliveries?.results?.find(
    (delivery) => delivery.supply_request && delivery.supply_request.id,
  )?.supply_request?.order?.id;

  const { mutate: upsertSupplyDeliveries, isPending: isUpsertingDeliveries } =
    useMutation({
      mutationFn: mutate(supplyDeliveryApi.upsertSupplyDelivery),
      onSuccess: () => {
        queryClient.invalidateQueries({
          queryKey: ["supplyDeliveries", deliveryOrderId],
        });
        queryClient.invalidateQueries({ queryKey: ["deliveryOrders"] });
        toast.success(t("supply_deliveries_updated_successfully"));
      },
      onError: (_error) => {
        toast.error(t("error_updating_supply_deliveries"));
      },
    });

  const { mutate: updateDeliveryOrder, isPending: isUpdating } = useMutation<
    DeliveryOrderRetrieve,
    Error,
    DeliveryOrderUpdate
  >({
    mutationFn: mutate(deliveryOrderApi.updateDeliveryOrder, {
      pathParams: {
        facilityId: facilityId,
        deliveryOrderId: deliveryOrderId,
      },
    }),
    onSuccess: (updatedDeliveryOrder: DeliveryOrderRetrieve) => {
      queryClient.invalidateQueries({
        queryKey: ["deliveryOrders", deliveryOrderId],
      });

      toast.success(
        updatedDeliveryOrder.status === DeliveryOrderStatus.pending
          ? t("order_marked_as_approved_successfully")
          : t("order_marked_as_successfully_toast", {
              status: t(updatedDeliveryOrder.status),
            }),
      );
    },
  });

  function handleSupplyDeliverySuccess() {
    queryClient.invalidateQueries({
      queryKey: ["supplyDeliveries", deliveryOrderId],
    });
  }

  function handleUpdateDeliveryOrderStatus(status: DeliveryOrderStatus) {
    if (!deliveryOrder) return;

    updateDeliveryOrder({
      ...deliveryOrder,
      status,
      supplier: deliveryOrder.supplier?.id || undefined,
      origin: deliveryOrder.origin?.id || undefined,
      destination: deliveryOrder.destination.id,
    });
  }

  function handleMarkAsAbandoned() {
    if (!supplyDeliveries?.results) return;

    const selectedSupplyDeliveries = supplyDeliveries.results
      .filter((delivery) => selectedDeliveries.includes(delivery.id))
      .map((delivery) => ({
        id: delivery.id,
        status: SupplyDeliveryStatus.abandoned,
        supplied_item_quantity: delivery.supplied_item_quantity,
        supplied_item_condition: delivery.supplied_item_condition,
        supplied_item_type: delivery.supplied_item_type,
        supply_request: delivery.supply_request?.id,
        extensions: delivery.extensions,
      }));

    if (selectedSupplyDeliveries.length === 0) {
      toast.error(t("please_select_at_least_one_delivery"));
      return;
    }

    upsertSupplyDeliveries({
      datapoints: selectedSupplyDeliveries,
    });
    setSelectedDeliveries([]);
  }

  function handleMarkAsDamaged() {
    if (!supplyDeliveries?.results) return;

    const selectedSupplyDeliveries = supplyDeliveries.results
      .filter((delivery) => selectedDeliveries.includes(delivery.id))
      .map((delivery) => ({
        id: delivery.id,
        status: SupplyDeliveryStatus.completed,
        supplied_item_quantity: delivery.supplied_item_quantity,
        supplied_item_condition: SupplyDeliveryCondition.damaged,
        supplied_item_type: delivery.supplied_item_type,
        supply_request: delivery.supply_request?.id,
        extensions: delivery.extensions,
      }));

    if (selectedSupplyDeliveries.length === 0) {
      toast.error(t("please_select_at_least_one_delivery"));
      return;
    }

    upsertSupplyDeliveries({
      datapoints: selectedSupplyDeliveries,
    });
    setSelectedDeliveries([]);
  }

  function handleSubmitDialog() {
    if (!supplyDeliveries?.results) return;

    const selectedSupplyDeliveries = supplyDeliveries.results
      .filter((delivery) => selectedDeliveries.includes(delivery.id))
      .map((delivery) => ({
        id: delivery.id,
        status: confirmDialog.status,
        supplied_item: delivery.supplied_item?.id,
        supplied_inventory_item: delivery.supplied_inventory_item?.id,
        supplied_item_quantity: delivery.supplied_item_quantity,
        supplied_item_condition: confirmDialog.condition,
        supplied_item_type: delivery.supplied_item_type,
        supply_request: delivery.supply_request?.id,
        extensions: delivery.extensions,
      }));

    upsertSupplyDeliveries({
      datapoints: selectedSupplyDeliveries,
    });
    setSelectedDeliveries([]);
    setConfirmDialog((prev) => ({ ...prev, open: false }));
  }

  function handleConfirmUpdateStock() {
    if (!supplyDeliveries?.results) return;

    if (selectedDeliveries.length === 0) {
      toast.error(t("please_select_at_least_one_delivery"));
      return;
    }

    setConfirmDialog({
      open: true,
      status: SupplyDeliveryStatus.completed,
      condition: SupplyDeliveryCondition.normal,
    });
  }

  if (isLoading) {
    return (
      <Page title={t("delivery_order_details")} hideTitleOnPage>
        <div className="space-y-4">
          <div className="animate-pulse">
            <div className="h-8 bg-gray-200 rounded w-1/3 mb-4"></div>
            <div className="h-4 bg-gray-200 rounded w-1/2 mb-2"></div>
            <div className="h-4 bg-gray-200 rounded w-3/4 mb-2"></div>
            <div className="h-4 bg-gray-200 rounded w-1/4"></div>
          </div>
        </div>
      </Page>
    );
  }

  if (!deliveryOrder) {
    return (
      <Page title={t("delivery_order_details")} hideTitleOnPage>
        <div className="space-y-4">
          <div className="text-center py-8">
            <p className="text-gray-500">{t("delivery_order_not_found")}</p>
          </div>
        </div>
      </Page>
    );
  }

  const canAddSupplyDeliveries =
    deliveryOrder.status === DeliveryOrderStatus.draft;

  const anyCompletedSupplyDeliveries =
    supplyDeliveries?.results?.some(
      (delivery) => delivery.status === SupplyDeliveryStatus.completed,
    ) ?? false;

  const canMarkAsCompleted =
    !!supplyDeliveries?.results?.length &&
    supplyDeliveries.results.every(
      (delivery) =>
        delivery.status === SupplyDeliveryStatus.completed ||
        delivery.status === SupplyDeliveryStatus.abandoned ||
        delivery.status === SupplyDeliveryStatus.entered_in_error,
    );

  const deliveryOrderStatusActions = getDeliveryOrderStatusActions(
    deliveryOrder.status,
    internal,
    anyCompletedSupplyDeliveries,
  );

  const inprogressSupplyDeliveries =
    supplyDeliveries?.results?.filter(
      (delivery) => delivery.status === SupplyDeliveryStatus.in_progress,
    ) ?? [];

  const hasReachedUpsertLimit =
    inprogressSupplyDeliveries.length >= careConfig.maxDatapointsPerUpsert;

  const isWithinUpsertLimit =
    selectedDeliveries.length <= careConfig.maxDatapointsPerUpsert;

  const activeSupplyDeliveries =
    supplyDeliveries?.results.filter((delivery) =>
      ACTIVE_SUPPLY_DELIVERY_STATUSES.some(
        (status) => status === delivery.status,
      ),
    ) ?? [];
  const cancelledDeliveriesCount =
    (supplyDeliveries?.results.length ?? 0) - activeSupplyDeliveries.length;
  const visibleSupplyDeliveries = showCancelledDeliveries
    ? (supplyDeliveries?.results ?? [])
    : activeSupplyDeliveries;

  return (
    <Page
      title={t("delivery_order_details")}
      hideTitleOnPage
      shortCutContext="facility:inventory:delivery"
      className="max-w-[100vw] mx-auto"
    >
      <div
        className={cn(
          "space-y-6",
          isSidebarOpen
            ? "md:max-w-[calc(100vw-22.5rem)]"
            : "md:max-w-[calc(100vw-9rem)]",
        )}
      >
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <Button
              size="icon"
              variant="outline"
              className="shrink-0"
              onClick={() =>
                navigate(
                  getInventoryBasePath(
                    facilityId,
                    locationId,
                    internal,
                    false,
                    isRequester,
                    "",
                  ),
                )
              }
            >
              <ChevronLeft />
            </Button>
            <div>
              <h4>{deliveryOrder.name}</h4>
              <p className="text-sm text-gray-700">
                <Trans
                  i18nKey="delivery_request_from_to"
                  values={{
                    from:
                      deliveryOrder.origin?.name ||
                      deliveryOrder.supplier?.name ||
                      t("origin"),
                    to: deliveryOrder.destination?.name || t("destination"),
                  }}
                  components={{
                    strong: <span className="font-semibold text-gray-700" />,
                  }}
                />
              </p>
            </div>
          </div>
          <div className="flex flex-wrap items-center justify-end gap-2">
            {supplyOrderId && (
              <Button variant="outline" asChild>
                <Link
                  href={`/inventory/internal/${isRequester ? "receive" : "dispatch"}/orders/${supplyOrderId}`}
                >
                  <Eye className="size-4" />{" "}
                  {isRequester
                    ? t("view_stock_request")
                    : t("view_dispatch_request")}
                </Link>
              </Button>
            )}
            <Button variant="outline" asChild>
              <Link href={`${deliveryOrderId}/print`}>
                <Printer className="size-4" /> {t("print")}
                <ShortcutBadge actionId="print-delivery-order" />
              </Link>
            </Button>

            {(!isRequester || !internal) &&
              deliveryOrder.status === DeliveryOrderStatus.draft &&
              (hasPendingItemChanges ? (
                <Button variant="outline" disabled>
                  <Edit /> {t("edit_order")}
                </Button>
              ) : (
                <Button variant="outline" asChild>
                  <Link href={`${deliveryOrderId}/edit`}>
                    <Edit /> {t("edit_order")}
                    <ShortcutBadge actionId="edit-order" />
                  </Link>
                </Button>
              ))}

            {deliveryOrder.status === DeliveryOrderStatus.draft && (
              <Button
                onClick={() =>
                  handleUpdateDeliveryOrderStatus(DeliveryOrderStatus.pending)
                }
                disabled={
                  isUpdating ||
                  hasPendingItemChanges ||
                  activeSupplyDeliveries.length === 0
                }
              >
                {isUpdating ? t("updating") : t("mark_as_approved")}
                <ShortcutBadge actionId="mark-as" />
              </Button>
            )}
            {deliveryOrder.status === DeliveryOrderStatus.pending &&
              isRequester && (
                <Button
                  onClick={() =>
                    handleUpdateDeliveryOrderStatus(
                      DeliveryOrderStatus.completed,
                    )
                  }
                  disabled={
                    isUpsertingDeliveries ||
                    isUpdating ||
                    selectedDeliveries.length !== 0 ||
                    !canMarkAsCompleted
                  }
                >
                  {isUpdating ? t("updating") : t("mark_as_completed")}
                  <ShortcutBadge actionId="mark-as" />
                </Button>
              )}

            {deliveryOrderStatusActions.length > 0 && (
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button
                    variant="outline"
                    size="icon"
                    disabled={hasPendingItemChanges}
                  >
                    <EllipsisVertical className="size-4" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end">
                  {deliveryOrderStatusActions.map((action) => {
                    return (
                      <DropdownMenuItem asChild key={action.status}>
                        <Button
                          variant="ghost"
                          onClick={() =>
                            setDeliveryOrderStatusDialog({
                              open: true,
                              status: action.status,
                            })
                          }
                          disabled={isUpdating}
                          className="w-full flex justify-stretch"
                        >
                          {action.icon}
                          <span>{t(action.label)}</span>
                        </Button>
                      </DropdownMenuItem>
                    );
                  })}
                </DropdownMenuContent>
              </DropdownMenu>
            )}
          </div>
        </div>

        {hasPendingItemChanges && (
          <p className="text-sm text-gray-600" role="status">
            {t("save_or_discard_delivery_changes")}
          </p>
        )}

        {/* Delivery Order Details */}
        <Card>
          <CardContent className="space-y-1 p-4">
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-3">
              <div>
                <label className="text-sm font-medium text-gray-700">
                  {t("deliver_to")}
                </label>
                <div className="text-lg font-semibold text-gray-950">
                  {deliveryOrder.destination.name}
                </div>
              </div>

              {deliveryOrder.origin && (
                <div>
                  <label className="text-sm font-medium text-gray-700">
                    {t("origin")}
                  </label>
                  <div className="text-lg font-semibold text-gray-950">
                    {deliveryOrder.origin.name}
                  </div>
                </div>
              )}

              {deliveryOrder.supplier && (
                <div>
                  <label className="text-sm font-medium text-gray-700">
                    {t("supplier")}
                  </label>
                  <div className="text-lg font-semibold text-gray-950">
                    {deliveryOrder.supplier.name}
                  </div>
                </div>
              )}

              <div>
                <label className="text-sm font-medium text-gray-700">
                  {t("status")}
                </label>
                <div>
                  <Badge
                    className="rounded-sm"
                    variant={DELIVERY_ORDER_STATUS_COLORS[deliveryOrder.status]}
                  >
                    {t(deliveryOrder.status)}
                  </Badge>
                </div>
              </div>

              {deliveryOrder.note && (
                <div>
                  <label className="text-sm font-medium text-gray-700">
                    {t("note")}
                  </label>
                  <p className="text-sm whitespace-pre-wrap">
                    {deliveryOrder.note}
                  </p>
                </div>
              )}

              <div className="flex flex-wrap gap-1">
                <div>
                  <label className="text-sm font-medium text-gray-700">
                    {t("tags_proper")}
                  </label>
                  <div className="flex flex-wrap gap-2">
                    <TagAssignmentSheet
                      entityType="delivery_order"
                      entityId={deliveryOrder.id}
                      facilityId={facilityId}
                      currentTags={deliveryOrder.tags ?? []}
                      onUpdate={() => {
                        queryClient.invalidateQueries({
                          queryKey: ["deliveryOrders", deliveryOrderId],
                        });
                      }}
                      trigger={
                        deliveryOrder.tags && deliveryOrder.tags.length > 0 ? (
                          <Button variant="outline" size="xs">
                            <Hash className="size-3" /> {t("tags")}
                          </Button>
                        ) : (
                          <Button variant="outline" size="xs">
                            <Hash className="size-3" /> {t("add_tags")}
                          </Button>
                        )
                      }
                    />
                    {deliveryOrder?.tags?.map((tag) => (
                      <TagBadge key={tag.id} tag={tag} className="rounded-sm" />
                    ))}
                  </div>
                </div>
              </div>

              {extensionFields.map((field) => {
                const value = getExtensionValue(
                  deliveryOrder.extensions as NamespacedExtensionData,
                  field,
                  {
                    delivery_order: deliveryOrder,
                    supply_deliveries: supplyDeliveries,
                  },
                );
                if (value === undefined || value === null) return null;

                const displayValue =
                  typeof value === "number"
                    ? value.toFixed(2)
                    : field.format === "date" || field.format === "date-time"
                      ? formatDateTime(value as string)
                      : String(value);

                return (
                  <div key={`${field.extensionName}-${field.name}`}>
                    <label className="text-sm font-medium text-gray-700">
                      {field.label}
                    </label>
                    <div className="text-lg font-semibold text-gray-950">
                      {displayValue}
                    </div>
                  </div>
                );
              })}
              {deliveryOrder.created_by && (
                <div>
                  <label className="text-sm font-medium text-gray-700">
                    {t("created_by")}
                  </label>
                  <div className="flex flex-col gap-0.5">
                    <span className="text-md font-semibold text-gray-950">
                      {formatName(deliveryOrder.created_by)}
                    </span>
                    <span className="text-xs text-gray-500">
                      {formatDateTime(deliveryOrder.created_date)}
                    </span>
                  </div>
                </div>
              )}
            </div>
          </CardContent>
        </Card>

        {/* Supply Deliveries Section */}
        <Card>
          <CardHeader className="text-lg flex flex-row flex-wrap items-center justify-between gap-2">
            <CardTitle>
              {isRequester
                ? deliveryOrder.status === DeliveryOrderStatus.completed
                  ? t("items_updated_stock")
                  : t("items_to_receive")
                : t("supply_deliveries")}
            </CardTitle>
            <div className="flex flex-wrap items-center gap-2">
              {cancelledDeliveriesCount > 0 && (
                <Button
                  variant="outline"
                  size="sm"
                  aria-pressed={showCancelledDeliveries}
                  onClick={() => setShowCancelledDeliveries((show) => !show)}
                >
                  <History className="size-4" />
                  {showCancelledDeliveries
                    ? t("hide_cancelled_items")
                    : t("show_cancelled_items", {
                        count: cancelledDeliveriesCount,
                      })}
                </Button>
              )}
              {deliveryOrder.status === DeliveryOrderStatus.pending && (
                <Button
                  variant="outline"
                  onClick={() => setShowAllDeliveries(true)}
                >
                  {t("view_all_deliveries")}
                  <ShortcutBadge actionId="all-deliveries" />
                </Button>
              )}

              {deliveryOrder.status === DeliveryOrderStatus.pending &&
                isRequester && (
                  <>
                    <Button
                      onClick={handleConfirmUpdateStock}
                      className="h-10"
                      disabled={
                        isUpdating ||
                        isUpsertingDeliveries ||
                        selectedDeliveries.length === 0 ||
                        !isWithinUpsertLimit
                      }
                    >
                      {isUpsertingDeliveries
                        ? t("updating")
                        : t("receive_update_stock")}
                      <ShortcutBadge actionId="enter-action" />
                    </Button>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="outline" size="icon" className="h-10">
                          <MoreVertical className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem
                          onClick={handleMarkAsAbandoned}
                          disabled={
                            isUpdating ||
                            isUpsertingDeliveries ||
                            selectedDeliveries.length === 0 ||
                            !isWithinUpsertLimit
                          }
                        >
                          {t("mark_as_abandoned")}
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={handleMarkAsDamaged}
                          disabled={
                            isUpdating ||
                            isUpsertingDeliveries ||
                            selectedDeliveries.length === 0 ||
                            !isWithinUpsertLimit
                          }
                        >
                          {t("mark_as_damaged")}
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </>
                )}
            </div>
          </CardHeader>
          {!isWithinUpsertLimit && (
            <div className="px-4">
              <UpsertLimitCallout>
                {t("max_deliveries_selected_limit", {
                  count: careConfig.maxDatapointsPerUpsert,
                })}
              </UpsertLimitCallout>
            </div>
          )}
          <CardContent className="p-2">
            {isLoadingSupplyDeliveries ? (
              <div className="space-y-2">
                {Array.from({ length: 3 }).map((_, i) => (
                  <div key={i} className="animate-pulse">
                    <div className="h-4 bg-gray-200 rounded w-3/4 mb-2"></div>
                    <div className="h-4 bg-gray-200 rounded w-1/2"></div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="space-y-6">
                {/* Existing Supply Deliveries Table */}
                {visibleSupplyDeliveries.length > 0 ? (
                  <div className="space-y-4">
                    <SupplyDeliveryTable
                      deliveries={visibleSupplyDeliveries}
                      showCheckbox={
                        deliveryOrder.status === DeliveryOrderStatus.pending &&
                        isRequester
                      }
                      autoSelectOnMount={
                        deliveryOrder.status === DeliveryOrderStatus.pending
                      }
                      selectedDeliveries={selectedDeliveries}
                      onDeliverySelect={(deliveryId, checked) => {
                        if (checked) {
                          setSelectedDeliveries([
                            ...selectedDeliveries,
                            deliveryId,
                          ]);
                        } else {
                          setSelectedDeliveries(
                            selectedDeliveries.filter(
                              (id) => id !== deliveryId,
                            ),
                          );
                        }
                      }}
                      onSelectAll={(checked) => {
                        if (checked) {
                          setSelectedDeliveries(
                            inprogressSupplyDeliveries.map((d) => d.id),
                          );
                        } else {
                          setSelectedDeliveries([]);
                        }
                      }}
                      internal={internal}
                      facilityId={facilityId}
                      linkToProduct
                      editingDeliveryIds={editingDeliveryIds}
                      onEditDelivery={
                        canAddSupplyDeliveries && !internal
                          ? (delivery) => {
                              deliveryFormRef.current?.editDelivery(delivery);
                            }
                          : undefined
                      }
                      onDeliveryClick={(delivery) => {
                        setShowAllDeliveries(true);
                        setSelectedProductKnowledgeDrawer(
                          internal
                            ? delivery.supplied_inventory_item?.product
                                ?.product_knowledge
                            : delivery.supplied_item?.product_knowledge,
                        );
                      }}
                      deliveryOrderStatus={deliveryOrder.status}
                    />
                  </div>
                ) : cancelledDeliveriesCount > 0 ? (
                  <p className="py-6 text-center text-sm text-gray-500">
                    {t("no_active_deliveries")}
                  </p>
                ) : null}

                {hasReachedUpsertLimit && canAddSupplyDeliveries && (
                  <UpsertLimitCallout>
                    {t("max_datapoints_per_upsert_limit", {
                      count: careConfig.maxDatapointsPerUpsert,
                    })}
                  </UpsertLimitCallout>
                )}

                {/* Add New Supply Delivery Form - Always show when in draft mode */}
                {canAddSupplyDeliveries && (
                  <div>
                    <AddSupplyDeliveryForm
                      ref={deliveryFormRef}
                      deliveryOrderId={deliveryOrderId}
                      facilityId={facilityId}
                      origin={deliveryOrder.origin?.id}
                      destination={deliveryOrder.destination.id}
                      onSuccess={handleSupplyDeliverySuccess}
                      supplyDeliveriesCount={inprogressSupplyDeliveries.length}
                      isFetchingSupplyDeliveries={isFetchingSupplyDeliveries}
                      currentSupplyDeliveries={supplyDeliveries?.results ?? []}
                      onEditingDeliveryIdsChange={setEditingDeliveryIds}
                      onPendingChangesChange={setHasPendingItemChanges}
                    />
                  </div>
                )}
              </div>
            )}
          </CardContent>
        </Card>

        <Drawer
          open={showAllDeliveries}
          onOpenChange={(open) => {
            setShowAllDeliveries(open);
            if (!open) {
              setTimeout(() => {
                setSelectedProductKnowledgeDrawer(undefined);
              }, 100);
            }
          }}
        >
          <DrawerContent className="max-w-7xl mx-auto px-4 sm:px-16 pb-10 ">
            <DrawerHeader>
              <DrawerTitle>{t("delivery_history")}</DrawerTitle>
              <DrawerDescription>
                {t("delivery_history_description")}
              </DrawerDescription>
            </DrawerHeader>
            <div>
              <div className="flex items-center justify-end px-4">
                <ProductKnowledgeSelect
                  value={selectedProductKnowledgeDrawer}
                  onChange={(value) => {
                    setSelectedProductKnowledgeDrawer(value);
                  }}
                  placeholder={t("filter_by_product")}
                  disableFavorites
                  alignContent="end"
                />
              </div>
              {deliveryOrder && (
                <AllSupplyDeliveriesComponent
                  facilityId={facilityId}
                  deliveryOrder={deliveryOrder}
                  locationId={locationId}
                  internal={internal}
                  isRequester={isRequester}
                  selectedProductKnowledge={selectedProductKnowledgeDrawer}
                />
              )}
            </div>
          </DrawerContent>
        </Drawer>

        <Dialog
          open={confirmDialog.open}
          onOpenChange={(open) =>
            setConfirmDialog((prev) => ({ ...prev, open }))
          }
        >
          <DialogContent>
            <DialogHeader>
              <DialogTitle>{t("receive_update_stock")}</DialogTitle>
              <DialogDescription>
                {t("apply_updates_selected", {
                  count: selectedDeliveries.length,
                })}
              </DialogDescription>
            </DialogHeader>

            <div className="space-y-6 bg-gray-50 p-4 rounded-md">
              <div className="space-y-4">
                <Label>{t("receiving_status")}</Label>
                <RadioGroup
                  value={confirmDialog.status}
                  onValueChange={(value: SupplyDeliveryStatus) =>
                    setConfirmDialog((prev) => ({ ...prev, status: value }))
                  }
                  className="flex flex-wrap gap-3"
                >
                  <Label
                    htmlFor={SupplyDeliveryStatus.completed}
                    className="flex items-center justify-center px-4 py-3 rounded-md border-[1.5px] cursor-pointer transition-all border-gray-300 bg-white hover:border-gray-400"
                  >
                    <RadioGroupItem
                      value={SupplyDeliveryStatus.completed}
                      id={SupplyDeliveryStatus.completed}
                    />
                    <div className="flex items-center space-x-2">
                      <span className="font-medium">{t("completed")}</span>
                    </div>
                  </Label>
                  <Label
                    htmlFor={SupplyDeliveryStatus.abandoned}
                    className="flex items-center justify-center px-4 py-3 rounded-md border-[1.5px] cursor-pointer transition-all border-gray-300 bg-white hover:border-gray-400"
                  >
                    <RadioGroupItem
                      value={SupplyDeliveryStatus.abandoned}
                      id={SupplyDeliveryStatus.abandoned}
                    />
                    <div className="flex items-center space-x-2">
                      <span className="font-medium">{t("abandoned")}</span>
                    </div>
                  </Label>
                </RadioGroup>
              </div>

              {confirmDialog.status === SupplyDeliveryStatus.completed && (
                <div className="space-y-4">
                  <Label>{t("item_condition")}</Label>
                  <RadioGroup
                    value={confirmDialog.condition}
                    onValueChange={(value: SupplyDeliveryCondition) =>
                      setConfirmDialog((prev) => ({
                        ...prev,
                        condition: value,
                      }))
                    }
                    className="flex flex-wrap gap-3"
                  >
                    <Label
                      htmlFor={SupplyDeliveryCondition.normal}
                      className="flex items-center justify-center px-4 py-3 rounded-md border-[1.5px] cursor-pointer transition-all border-gray-300 bg-white hover:border-gray-400"
                    >
                      <RadioGroupItem
                        value={SupplyDeliveryCondition.normal}
                        id={SupplyDeliveryCondition.normal}
                      />
                      <div className="flex items-center space-x-2">
                        <span className="font-medium">{t("normal")}</span>
                      </div>
                    </Label>
                    <Label
                      htmlFor={SupplyDeliveryCondition.damaged}
                      className="flex items-center justify-center px-4 py-3 rounded-md border-[1.5px] cursor-pointer transition-all border-gray-300 bg-white hover:border-gray-400"
                    >
                      <RadioGroupItem
                        value={SupplyDeliveryCondition.damaged}
                        id={SupplyDeliveryCondition.damaged}
                      />
                      <div className="flex items-center space-x-2">
                        <span className="font-medium">{t("damaged")}</span>
                      </div>
                    </Label>
                  </RadioGroup>
                </div>
              )}
            </div>

            <DialogFooter>
              <Button
                variant="outline"
                onClick={() =>
                  setConfirmDialog((prev) => ({ ...prev, open: false }))
                }
              >
                {t("cancel")}
              </Button>
              <Button
                variant={
                  confirmDialog.status === SupplyDeliveryStatus.abandoned
                    ? "destructive"
                    : "primary"
                }
                onClick={handleSubmitDialog}
                disabled={isUpsertingDeliveries}
              >
                {isUpsertingDeliveries ? t("updating") : t("confirm")}
                <ShortcutBadge actionId="submit-action" />
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>

        <ConfirmActionDialog
          open={deliveryOrderStatusDialog.open}
          onOpenChange={(open) =>
            setDeliveryOrderStatusDialog((prev) => ({ ...prev, open }))
          }
          title={
            deliveryOrderStatusDialog.status === DeliveryOrderStatus.draft
              ? t("mark_as_draft")
              : deliveryOrderStatusDialog.status ===
                  DeliveryOrderStatus.entered_in_error
                ? t("mark_as_entered_in_error")
                : t("mark_as_abandoned")
          }
          description={
            deliveryOrderStatusDialog.status === DeliveryOrderStatus.draft
              ? t("mark_order_as_draft_confirmation_description")
              : deliveryOrderStatusDialog.status ===
                  DeliveryOrderStatus.entered_in_error
                ? t("mark_order_as_entered_in_error_confirmation_description")
                : t("mark_order_as_abandoned_confirmation_description")
          }
          confirmText={t("confirm")}
          variant={
            deliveryOrderStatusDialog.status === DeliveryOrderStatus.draft
              ? "primary"
              : "destructive"
          }
          onConfirm={() => {
            if (deliveryOrderStatusDialog.status) {
              handleUpdateDeliveryOrderStatus(deliveryOrderStatusDialog.status);
            }
            setDeliveryOrderStatusDialog({ open: false, status: null });
          }}
          disabled={isUpdating}
        />
      </div>
    </Page>
  );
}

import { faker } from "@faker-js/faker";
import {
  expect,
  test,
  type APIResponse,
  type Locator,
  type Page,
} from "@playwright/test";
import { getApiHeaders, getApiUrl } from "tests/helper/utils";
import { getFacilityId } from "tests/support/facilityId";

import type { ChargeItemDefinitionRead } from "@/types/billing/chargeItemDefinition/chargeItemDefinition";
import type { ProductKnowledgeBase } from "@/types/inventory/productKnowledge/productKnowledge";

test.use({ storageState: "tests/.auth/user.json" });

interface ProductFixture {
  id: string;
  product_knowledge: { id: string; slug: string; name: string };
  charge_item_definition?: {
    slug: string;
    category?: { slug: string };
    price_components?: Record<string, unknown>[];
    [key: string]: unknown;
  } | null;
  purchase_price?: string | null;
  batch?: { lot_number?: string } | null;
  expiration_date?: string | null;
  extensions?: Record<string, unknown>;
}

interface DeliveryItem {
  id: string;
  status: string;
  supplied_item_quantity: string;
  supplied_item_pack_quantity: number;
  supplied_item_pack_size: number;
  supplied_item: { id: string; product_knowledge?: { slug: string } };
  supply_request?: { id: string };
}

async function responseData<T>(response: APIResponse): Promise<T> {
  expect(response.ok(), await response.text()).toBeTruthy();
  return response.json();
}

async function scrollTableRight(table: Locator) {
  await table.scrollIntoViewIfNeeded();
  const scrollLeft = await table.evaluate((element) => {
    const container = element.parentElement;
    if (!container) throw new Error("The table must have a scroll container");
    container.scrollLeft = container.scrollWidth;
    return container.scrollLeft;
  });
  expect(scrollLeft).toBeGreaterThan(0);
}

async function createExternalDeliveryDraft(
  page: Page,
  options: { metadata?: boolean; withoutPricingMetadata?: boolean } = {},
) {
  const facilityId = getFacilityId();
  const apiUrl = getApiUrl();
  const headers = getApiHeaders();
  const batch = `edit-${faker.string.alphanumeric(10)}`;
  const orderName = `Delivery edit ${faker.string.alphanumeric(10)}`;

  const locations = await responseData<{
    results: { id: string; name: string }[];
  }>(
    await page.request.get(
      `${apiUrl}/api/v1/facility/${facilityId}/location/?mode=kind&limit=100`,
      { headers },
    ),
  );
  const location = locations.results.find(({ name }) => name === "Pharmacy");
  expect(
    location,
    "The test facility must include its Pharmacy fixture",
  ).toBeDefined();
  const locationId = location!.id;

  const products = await responseData<{ results: ProductFixture[] }>(
    await page.request.get(
      `${apiUrl}/api/v1/facility/${facilityId}/product/?limit=100`,
      { headers },
    ),
  );
  const referenceProduct = products.results.find(
    ({ charge_item_definition }) => charge_item_definition?.category?.slug,
  );
  expect(
    referenceProduct,
    "The test facility must include a priced product fixture",
  ).toBeDefined();

  const referenceKnowledge = await responseData<ProductKnowledgeBase>(
    await page.request.get(
      `${apiUrl}/api/v1/product_knowledge/${referenceProduct!.product_knowledge.slug}/`,
      { headers },
    ),
  );
  const productKnowledge = await responseData<ProductKnowledgeBase>(
    await page.request.post(`${apiUrl}/api/v1/product_knowledge/`, {
      headers,
      data: {
        status: "active",
        product_type: "consumable",
        name: `Delivery product ${faker.string.alphanumeric(10)}`,
        slug_value: faker.string.uuid(),
        facility: facilityId,
        base_unit: referenceKnowledge.base_unit,
        names: [],
        storage_guidelines: [],
        definitional: null,
      },
    }),
  );
  const referenceDefinition = await responseData<ChargeItemDefinitionRead>(
    await page.request.get(
      `${apiUrl}/api/v1/facility/${facilityId}/charge_item_definition/${referenceProduct!.charge_item_definition!.slug}/`,
      { headers },
    ),
  );
  let chargeItemSlug: string | undefined;
  if (!options.withoutPricingMetadata) {
    const definition = await responseData<{ slug: string }>(
      await page.request.post(
        `${apiUrl}/api/v1/facility/${facilityId}/charge_item_definition/`,
        {
          headers,
          data: {
            slug_value: faker.string.uuid(),
            category: referenceDefinition.category?.slug ?? null,
            title: `Metadata pricing ${faker.string.alphanumeric(10)}`,
            status: "active",
            can_edit_charge_item: options.metadata
              ? true
              : referenceDefinition.can_edit_charge_item,
            discount_configuration: options.metadata
              ? { max_applicable: 1, applicability_order: "total_desc" }
              : referenceDefinition.discount_configuration,
            derived_from_uri: options.metadata
              ? "urn:care:delivery-edit:source"
              : referenceDefinition.derived_from_uri,
            description: options.metadata
              ? "Retain the existing pricing description"
              : referenceDefinition.description,
            purpose: options.metadata
              ? "Retain the existing pricing purpose"
              : referenceDefinition.purpose,
            price_components: options.metadata
              ? [
                  {
                    monetary_component_type: "base",
                    amount: "10.123456",
                    code: {
                      system: "urn:care:delivery-edit",
                      code: "base-reference",
                      display: "Base reference",
                    },
                  },
                  {
                    monetary_component_type: "surcharge",
                    amount: "2.5",
                    code: {
                      system: "urn:care:delivery-edit",
                      code: "handling-fee",
                      display: "Handling fee",
                    },
                  },
                  {
                    monetary_component_type: "tax",
                    factor: "18",
                    code: {
                      system: "urn:care:delivery-edit",
                      code: "tax-reference",
                      display: "Tax reference",
                    },
                  },
                  {
                    monetary_component_type: "discount",
                    factor: "5",
                    code: {
                      system: "urn:care:delivery-edit",
                      code: "discount-reference",
                      display: "Discount reference",
                    },
                  },
                ]
              : [{ monetary_component_type: "base", amount: "10" }],
          },
        },
      ),
    );
    chargeItemSlug = definition.slug;
  }
  if (options.metadata) {
    const tag = await responseData<{ id: string }>(
      await page.request.post(`${apiUrl}/api/v1/tag_config/`, {
        headers,
        data: {
          display: `Metadata tag ${faker.string.alphanumeric(10)}`,
          description: "Preserve the source pricing tag when cloning",
          category: "admin",
          status: "active",
          resource: "charge_item_definition",
          facility: facilityId,
        },
      }),
    );
    await responseData(
      await page.request.post(
        `${apiUrl}/api/v1/facility/${facilityId}/charge_item_definition/${chargeItemSlug}/set_tags/`,
        { headers, data: { tags: [tag.id] } },
      ),
    );
  }

  const product = await responseData<ProductFixture>(
    await page.request.post(
      `${apiUrl}/api/v1/facility/${facilityId}/product/`,
      {
        headers,
        data: {
          status: "active",
          product_knowledge: productKnowledge.slug,
          charge_item_definition: options.withoutPricingMetadata
            ? null
            : chargeItemSlug,
          ...(!options.withoutPricingMetadata && {
            batch: { lot_number: batch },
            expiration_date: "2031-01-31",
          }),
          standard_pack_size: 5,
          purchase_price: options.withoutPricingMetadata ? null : "2.5",
          extensions: options.metadata
            ? { core: { audit_marker: "preserve-product-metadata" } }
            : {},
        },
      },
    ),
  );
  const supplier = await responseData<{ id: string }>(
    await page.request.post(`${apiUrl}/api/v1/organization/`, {
      headers,
      data: {
        name: `Delivery supplier ${faker.string.alphanumeric(10)}`,
        org_type: "product_supplier",
      },
    }),
  );
  const order = await responseData<{ id: string }>(
    await page.request.post(
      `${apiUrl}/api/v1/facility/${facilityId}/order/delivery/`,
      {
        headers,
        data: {
          name: orderName,
          status: "draft",
          supplier: supplier.id,
          destination: locationId,
          extensions: {},
        },
      },
    ),
  );
  const deliveryPayload = {
    supplied_item_type: "product",
    supplied_item_condition: "normal",
    supplied_item: product.id,
    supplied_item_pack_quantity: 2,
    supplied_item_pack_size: 5,
    supplied_item_quantity: "10",
    total_purchase_price: "25",
    order: order.id,
    extensions: {},
  };
  const original = await responseData<{ id: string }>(
    await page.request.post(`${apiUrl}/api/v1/supply_delivery/`, {
      headers,
      data: { ...deliveryPayload, status: "in_progress" },
    }),
  );
  for (const status of ["abandoned", "entered_in_error"]) {
    await responseData(
      await page.request.post(`${apiUrl}/api/v1/supply_delivery/`, {
        headers,
        data: { ...deliveryPayload, status },
      }),
    );
  }

  const deliveryUrl = `/facility/${facilityId}/locations/${locationId}/inventory/external/deliveries/outgoing/${order.id}`;
  return {
    facilityId,
    apiUrl,
    headers,
    batch,
    orderName,
    locationId,
    product,
    supplier,
    order,
    original,
    deliveryUrl,
  };
}

test.describe("External delivery draft items", () => {
  test("loads and saves one purchase request item at a time", async ({
    page,
  }) => {
    const fixture = await createExternalDeliveryDraft(page);
    const requestPayload = {
      name: `Delivery request ${faker.string.alphanumeric(10)}`,
      status: "draft",
      supplier: fixture.supplier.id,
      destination: fixture.locationId,
      intent: "order",
      category: "nonstock",
      priority: "routine",
      reason: "ward_stock",
    };
    const requestOrder = await responseData<{ id: string }>(
      await page.request.post(
        `${fixture.apiUrl}/api/v1/facility/${fixture.facilityId}/order/request/`,
        { headers: fixture.headers, data: requestPayload },
      ),
    );
    const requests: { id: string; quantity: number }[] = [];
    for (const quantity of [15, 20]) {
      const request = await responseData<{ id: string }>(
        await page.request.post(`${fixture.apiUrl}/api/v1/supply_request/`, {
          headers: fixture.headers,
          data: {
            status: "active",
            quantity: String(quantity),
            item: fixture.product.product_knowledge.id,
            order: requestOrder.id,
          },
        }),
      );
      requests.push({ id: request.id, quantity });
    }
    await responseData(
      await page.request.put(
        `${fixture.apiUrl}/api/v1/facility/${fixture.facilityId}/order/request/${requestOrder.id}/`,
        {
          headers: fixture.headers,
          data: { ...requestPayload, status: "pending" },
        },
      ),
    );
    await page.goto(`${fixture.deliveryUrl}?supplyOrder=${requestOrder.id}`);
    const form = page.getByRole("form", {
      name: "Pending changes",
      exact: true,
    });
    const requestPicker = page.getByRole("dialog", {
      name: "Select Item",
      exact: true,
    });

    for (const [index, request] of requests.entries()) {
      await page.getByRole("button", { name: /^Load from order\b/ }).click();
      await expect(page.getByRole("dialog")).toBeVisible();
      await expect(page.getByRole("dialog").getByRole("checkbox")).toHaveCount(
        0,
      );
      await expect(requestPicker).toBeVisible();
      await requestPicker
        .getByText(new RegExp(`^${request.quantity}(?:\\.0+)?\\s`))
        .locator("..")
        .getByRole("radio")
        .check();
      await expect(
        requestPicker.getByRole("radio", { checked: true }),
      ).toHaveCount(1);
      await requestPicker.getByRole("button", { name: /^Done\b/ }).click();

      await expect(requestPicker).not.toBeVisible();
      await expect(page.getByRole("dialog")).toHaveCount(0);
      await expect(form).toBeVisible();
      await expect(form.locator("tbody tr")).toHaveCount(1);
      await expect(form.getByRole("combobox")).toHaveCount(1);
      await expect(form.getByRole("combobox")).toContainText(
        fixture.product.product_knowledge.name,
      );
      await expect(
        form.getByRole("button", { name: "Add Another", exact: true }),
      ).toHaveCount(0);
      await expect(
        form.getByRole("button", { name: /^Load from order\b/ }),
      ).toHaveCount(0);
      const packQuantity = request.quantity / 5;
      await form
        .getByRole("spinbutton", { name: "Pack Qty", exact: true })
        .fill(String(packQuantity));
      await form.getByRole("button", { name: /^Save Changes\b/ }).click();
      await expect(form).not.toBeVisible();

      const persisted = await responseData<{ results: DeliveryItem[] }>(
        await page.request.get(
          `${fixture.apiUrl}/api/v1/supply_delivery/?order=${fixture.order.id}&facility=${fixture.facilityId}`,
          { headers: fixture.headers },
        ),
      );
      const linked = persisted.results.filter(
        (delivery) => delivery.supply_request,
      );
      expect(linked).toHaveLength(index + 1);
      expect(
        linked.find((delivery) => delivery.supply_request?.id === request.id)
          ?.supplied_item_quantity,
      ).toMatch(new RegExp(`^${packQuantity * 5}(?:\\.0+)?$`));
    }
  });

